#!/usr/bin/env python3
"""Offline, no-network readable explorer generated from private roadmap outputs."""
import json, pathlib, argparse, html

def create_viewer(root,out):
 root=pathlib.Path(root);meta=json.loads((root/'ROADMAP_ROOT.json').read_text());houses=json.loads((root/'HOUSE_MODULES_12.json').read_text())
 spheres=[json.loads(s) for s in (root/'SPHERE_PATHWAYS_144.jsonl').read_text().splitlines()]
 rows=[json.loads(s) for s in (root/'NODE_SEEDS_1728.jsonl').read_text().splitlines()]
 # Rich full source and candidates remain in separate private JSONL. Viewer exposes concise node-plan view only.
 cards=[{'id':n['coordinate'],'name':n['nodeName'],'h':n['house'],'s':n['sphere'],'houseName':n['houseName'],
   'sphereName':n['sphereName'],'role':n['role'],'metric':n['metricFamily'],'metricId':n['metricId'],
   'stage':n['stage'],'gain':n['gainStatus'],'primary':n['openalex']['primaryCount'],'alternate':n['openalex']['alternateCount'],
   'sourceSha':n['sourceRecordSHA256'],'change':n['specificChange'],'test':n['acceptanceTest'],
   'negative':n['negativeTest'],'definition':n['definition']} for n in rows]
 minimal_h=[{'id':h['id'],'name':h['name'],'function':h['existingAtlasOneCapability']} for h in houses]
 minimal_s=[{'id':s['id'],'name':s['name'],'h':s['house'],'role':s['role'],'adapter':s['proposedAdapter']} for s in spheres]
 payload=json.dumps({'head':meta,'houses':minimal_h,'spheres':minimal_s,'nodes':cards},ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
 template=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas 1728 — Complete Civilizational Roadmap</title>
<style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial;color:#eaf2f6;background:#07111d}*{box-sizing:border-box}body{margin:0}header{background:linear-gradient(110deg,#0d2436,#101833 50%,#132c35);border-bottom:1px solid #29485d;padding:32px max(18px,calc((100vw - 1200px)/2))}header h1{font-size:clamp(24px,4vw,42px);letter-spacing:-1.5px;line-height:1.05;margin:7px 0 10px}header p{max-width:920px;line-height:1.55;color:#b7ced9}.eyebrow{text-transform:uppercase;letter-spacing:.18em;color:#76e6cb;font-size:11px;font-weight:800}.statgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;max-width:1080px;margin-top:21px}.stat{background:#081b2b;border:1px solid #275066;padding:14px;border-radius:11px}.stat strong{display:block;font-size:27px;color:#eff9fa;font-variant-numeric:tabular-nums}.stat small{color:#9fbbc5}main{max-width:1200px;margin:0 auto;padding:24px 18px}.layout{display:grid;grid-template-columns:minmax(310px,1.2fr) minmax(300px,.8fr);gap:17px}.panel{border:1px solid #2b475b;border-radius:12px;background:#0b1a28;overflow:hidden}.panelhead{padding:15px 18px;border-bottom:1px solid #274257;display:flex;align-items:center;justify-content:space-between;gap:12px}.panelhead h2{font-size:16px;margin:0}.controls{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:8px;padding:14px 16px}.controls input,.controls select{min-width:0;background:#101f2e;color:#f5f7fa;border:1px solid #416175;padding:11px 10px;border-radius:7px;font:inherit;font-size:13px}.controls input:focus,.controls select:focus,button:focus-visible{outline:2px solid #9ae7d3;outline-offset:2px}.small{color:#a1b8c5;font-size:12px}.list{max-height:64vh;overflow:auto;padding:4px 11px 12px}.item{width:100%;border:1px solid #203e51;background:#0e2232;color:inherit;padding:12px 14px;margin-top:6px;border-radius:8px;text-align:left;cursor:pointer;display:grid;grid-template-columns:100px 1fr 96px;gap:10px;align-items:center}.item:hover,.item[aria-pressed=true]{border-color:#76e6cb;background:#123246}.tag{background:#193c45;color:#a9ead8;padding:3px 6px;border-radius:4px;font-size:11px;font-variant-numeric:tabular-nums}.item strong{font-size:13px}.item small{color:#acc1cd;font-size:11px}.pager{display:flex;gap:8px;justify-content:flex-end;align-items:center;padding:10px 18px;border-top:1px solid #274257}button{background:#173346;color:#e9faf3;border:1px solid #3f7981;border-radius:7px;padding:9px 12px;cursor:pointer}button:disabled{opacity:.4;cursor:default}.detail{padding:18px;max-height:75vh;overflow:auto}.detail h3{font-size:20px;margin:6px 0}.detail dl{display:grid;grid-template-columns:105px 1fr;gap:6px 12px;font-size:13px}.detail dt{color:#87bba9}.detail dd{margin:0;overflow-wrap:anywhere}.detail section{border-top:1px solid #25465b;margin-top:14px;padding-top:13px}.detail p{color:#c4d7de;font-size:13px;line-height:1.58}.badge{display:inline-block;border:1px solid #807947;color:#f3da8a;border-radius:6px;padding:4px 7px;font-size:11px}footer{color:#9ab4c0;padding:24px 0 45px;font-size:12px;line-height:1.55}@media(max-width:900px){.layout{grid-template-columns:1fr}.controls{grid-template-columns:1fr 1fr}.statgrid{grid-template-columns:repeat(2,1fr)}.list{max-height:45vh}}@media(max-width:480px){.controls{grid-template-columns:1fr}.item{grid-template-columns:88px 1fr}.item small{display:none}.statgrid{grid-template-columns:repeat(2,1fr)}.stat strong{font-size:22px}}
</style></head><body><header><div class="eyebrow">Ariadne source-bound • Review roadmap • Offline / no network</div><h1>One civilization. One codebase.<br>1,728 measurable seeds.</h1><p>Twelve existing House functions coordinate 144 distinct Sphere implementation contracts and 1,728 original Ariadne node work orders. Each metric is a planned, falsifiable experiment—not an earned performance gain.</p><div class="statgrid"><div class="stat"><strong>12</strong><small>House function bindings</small></div><div class="stat"><strong>144</strong><small>Sphere pathway plans</small></div><div class="stat"><strong>1,728</strong><small>Node metrics specified</small></div><div class="stat"><strong>0</strong><small>New gains claimed</small></div></div></header><main><div class="layout"><div class="panel"><div class="panelhead"><h2>Ariadne node work orders</h2><span class="small" id="resultCount">1,728 planned</span></div><div class="controls"><input id="search" type="search" aria-label="Search coordinates and subjects" placeholder="Search HSN, Sphere, metric, subject"><select id="house" aria-label="House"><option value="">All Houses</option></select><select id="sphere" aria-label="Sphere"><option value="">All Spheres</option></select><select id="role" aria-label="Role"><option value="">All roles</option><option value="DOMAIN_SPECIALIZATION">Domain</option><option value="EPISTEMIC_META">Method</option></select></div><div id="list" class="list" role="list"></div><div class="pager"><span class="small" id="pageInfo"></span><button id="previous">Previous</button><button id="next">Next 48</button></div></div><div class="panel"><div class="panelhead"><h2>Work order details</h2><span class="badge">SPECIFIED · NOT IMPLEMENTED</span></div><article class="detail" id="detail" aria-live="polite" tabindex="-1"></article></div></div><footer>Source IDs from exact Ariadne v0.7, source SHA <code id="rootsha"></code>. Topic matches: frozen historical OpenAlex candidates only. Atlas EX.W.C.P engineering program is a separate namespace. Not a hosted or authorized SwarmChat reader. Public release requires human-root permission, consent, licensed source review, and host READ/RETURN recheck.</footer></main><script type="application/json" id="db">__PAYLOAD__</script><script>
'use strict';const DB=JSON.parse(document.getElementById('db').textContent);const $=s=>document.getElementById(s);const PAGE=48;let offset=0,selection=null;const byId=new Map(DB.nodes.map(n=>[n.id,n]));let current=DB.nodes;const qtext=n=>[n.id,n.name,n.sphereName,n.houseName,n.metric].join(' ').toLocaleLowerCase();const searchIndex=DB.nodes.map(qtext);
function opt(select,text,value){let o=document.createElement('option');o.textContent=text;o.value=value;select.appendChild(o)}for(const h of DB.houses)opt($('house'),h.id+' — '+h.name,h.id);for(const s of DB.spheres)opt($('sphere'),s.id+' — '+s.name,s.id);$('rootsha').textContent=DB.head.sourceSHA256;
function node(t,tag='span',cls=''){let e=document.createElement(tag);if(cls)e.className=cls;e.textContent=t;return e}function dt(dl,k,v){dl.append(node(k,'dt'));dl.append(node(String(v),'dd'))}
function detail(n){selection=n.id;let dst=$('detail');dst.replaceChildren();dst.append(node(n.id,'div','eyebrow'),node(n.name,'h3'));dst.append(node(n.sphereName+' · '+n.houseName,'p'));let dl=document.createElement('dl');dt(dl,'Role',n.role);dt(dl,'Metric',n.metricId);dt(dl,'Measure',n.metric);dt(dl,'Evidence',n.stage);dt(dl,'OpenAlex',n.primary+' primary · '+n.alternate+' alternate');dt(dl,'Source record',n.sourceSha||'Synthetic fixture');dst.appendChild(dl);for(const [k,v] of [['Original definition',n.definition],['Proposed code seed',n.change],['Acceptance test',n.test],['Negative falsifier',n.negative]]){let sec=document.createElement('section');sec.append(node(k,'div','eyebrow'),node(v,'p'));dst.appendChild(sec)}dst.append(node('No actual baseline, gain, model training, CANON approval or host permission is claimed.','p'));}
function draw(){let frag=document.createDocumentFragment();for(const n of current.slice(offset,offset+PAGE)){let b=document.createElement('button');b.type='button';b.className='item';b.setAttribute('aria-pressed',n.id===selection?'true':'false');b.append(node(n.id,'span','tag'));b.append(node(n.name,'strong'));b.append(node(n.stage==='SPECIFIED_NOT_IMPLEMENTED'?'PLANNED':'REVIEW','small'));b.addEventListener('click',()=>{detail(n);draw()});frag.append(b)}$('list').replaceChildren(frag);$('resultCount').textContent=current.length.toLocaleString()+' of 1,728';$('pageInfo').textContent=(current.length?offset+1:0)+'–'+Math.min(offset+PAGE,current.length)+' / '+current.length; $('previous').disabled=offset===0;$('next').disabled=offset+PAGE>=current.length;}
function filter(){const q=$('search').value.trim().toLocaleLowerCase(),h=$('house').value,s=$('sphere').value,role=$('role').value;const subset=[];for(let i=0;i<DB.nodes.length;i++){let n=DB.nodes[i];if(q&&!searchIndex[i].includes(q))continue;if(h&&n.h!==h)continue;if(s&&n.s!==s)continue;if(role&&n.role!==role)continue;subset.push(n)}current=subset;offset=0;draw();if(!byId.has(selection)||!subset.some(n=>n.id===selection)){detail(subset[0]||{id:'No results',name:'No matching work order',sphereName:'',houseName:'',role:'',metricId:'',metric:'',stage:'',primary:0,alternate:0,sourceSha:'',definition:'Try a different filter',change:'',test:'',negative:''})}}
$('search').addEventListener('input',filter);for(const x of ['house','sphere','role'])$(x).addEventListener('change',()=>{if(x==='house'&&$('house').value){$('sphere').value=''}filter()});$('next').addEventListener('click',()=>{offset+=PAGE;draw()});$('previous').addEventListener('click',()=>{offset=Math.max(0,offset-PAGE);draw()});detail(DB.nodes[0]);draw();
</script></body></html>'''
 path=pathlib.Path(out);path.write_text(template.replace('__PAYLOAD__',payload),encoding='utf-8');return len(cards)

if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--root',required=True);ap.add_argument('--out',required=True);args=ap.parse_args();print('rendered',create_viewer(args.root,args.out))
